      "mainEntity": [
        {
          "@type": "Question",
          "name": "Does a dripping mixer always need replacing?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. The cause, fitting condition and availability of compatible parts need assessment. Ask the quote to distinguish a repair from product supply and installation if replacement is recommended."
          }
        },
        {
          "@type": "Question",
          "name": "Can I supply the replacement mixer myself?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Discuss the product and existing connections first. Dimensions, mounting and compatibility can affect installation. The quote should identify who supplies the fitting and whether additional connection work is required."
          }
        },
        {
          "@type": "Question",
          "name": "Why does a tap keep dripping after it is turned off?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A worn seal or fitting fault can let water pass after shut-off; an outlet drip and base leak need different checks. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Can a dripping tap waste water over time?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Continued dripping wastes water; the amount depends on the actual rate and how long it continues. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Can I supply my own replacement mixer tap?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, if the selected mixer suits the installation. Confirm compatibility and the installation inclusions before buying. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Do I need to diagnose the problem first?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Describe the observable change and property context. We inspect the affected area on site to establish the cause and confirm the repair scope. If more access is needed, we agree it with you first."
          }
        },
        {
          "@type": "Question",
          "name": "Can I send photos?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Photos are optional: email safely taken photos to maxinemaintenance.au@outlook.com. You can contact us without photos. Do not approach a hazard, remove covers or dismantle equipment to take a photo."
          }
        },
        {
          "@type": "Question",
          "name": "Can you help with a dripping tap?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Tell us the fixture location, whether it drips constantly and any other changes you have noticed."
          }
        },
        {
          "@type": "Question",
          "name": "Should I try to dismantle a mixer?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. It is safer to describe the problem and leave the fitting intact for assessment."
          }
        },
        {
          "@type": "Question",
          "name": "Do you work on rental-property fixtures?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Property managers can include work-order and access details."
          }
        },
        {
          "@type": "Question",
          "name": "Can you install a tap I have already purchased?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "We assess the product specifications, mounting arrangement and connection compatibility before agreeing the installation. Tell us whether product supply or installation only is required so the written quote covers the right scope."
          }
        }
      ]
